#!/usr/bin/env node
// Turn data/*.csv into a runnable SQL reconcile script.
//
// This exists so a fresh database can be brought up entirely from migrations, with
// no extra tooling step: the generated file is applied like any other migration.
// For ongoing edits prefer scripts/sync-title-keywords.mjs, which does the same
// reconcile over the network without writing a new migration.
//
//   node scripts/build-title-keyword-seed.mjs [outputPath]
//
// Default output: work/title-keyword-sync.sql

import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const projectRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const outputPath = resolve(projectRoot, process.argv[2] ?? "work/title-keyword-sync.sql");

function parseCsv(text) {
  const rows = [];
  let row = [];
  let field = "";
  let quoted = false;
  for (let index = 0; index < text.length; index += 1) {
    const character = text[index];
    if (quoted) {
      if (character === '"' && text[index + 1] === '"') { field += '"'; index += 1; continue; }
      if (character === '"') { quoted = false; continue; }
      field += character;
      continue;
    }
    if (character === '"') { quoted = true; continue; }
    if (character === ",") { row.push(field); field = ""; continue; }
    if (character === "\r") continue;
    if (character === "\n") { row.push(field); rows.push(row); row = []; field = ""; continue; }
    field += character;
  }
  row.push(field);
  if (row.some((cell) => cell.trim())) rows.push(row);
  const header = rows.shift()?.map((cell) => cell.trim()) ?? [];
  return rows
    .filter((cells) => cells.some((cell) => cell.trim()) && !cells[0].trim().startsWith("#"))
    .map((cells) => Object.fromEntries(header.map((name, position) => [name, (cells[position] ?? "").trim()])));
}

const quote = (value) => `'${String(value ?? "").replace(/'/g, "''")}'`;

function read(fileName) {
  return parseCsv(readFileSync(resolve(projectRoot, "data", fileName), "utf8"));
}

const seniority = read("seniority_map.csv");
const department = read("department_map.csv");

const lines = [
  "-- GENERATED by scripts/build-title-keyword-seed.mjs -- edit data/*.csv, not this file.",
  "--",
  "-- Reconciles the classifier keyword tables to match the CSVs exactly: upsert every",
  "-- row present, delete every row that is not. Safe to re-run.",
  "",
  "begin;",
  "",
  "insert into public.title_seniority_keywords(keyword, tier, notes) values",
  seniority.map((row) => `  (${quote(row.keyword)}, ${quote(row.tier)}, ${quote(row.notes)})`).join(",\n"),
  "on conflict (keyword) do update set tier = excluded.tier, notes = excluded.notes;",
  "",
  "delete from public.title_seniority_keywords where keyword not in (",
  seniority.map((row) => `  ${quote(row.keyword)}`).join(",\n"),
  ");",
  "",
  "insert into public.title_department_keywords(keyword, department, sub_department, notes) values",
  department.map((row) => `  (${quote(row.keyword)}, ${quote(row.department)}, ${quote(row.sub_department)}, ${quote(row.notes)})`).join(",\n"),
  "on conflict (keyword) do update set department = excluded.department, sub_department = excluded.sub_department, notes = excluded.notes;",
  "",
  "delete from public.title_department_keywords where keyword not in (",
  department.map((row) => `  ${quote(row.keyword)}`).join(",\n"),
  ");",
  "",
  "commit;",
  "",
];

mkdirSync(dirname(outputPath), { recursive: true });
writeFileSync(outputPath, lines.join("\n"), "utf8");
console.log(`${outputPath}: ${seniority.length} seniority + ${department.length} department keywords`);
